using System.Diagnostics;
using System.Runtime.InteropServices;
using System.Text;
using System.IO;
public sealed class M12SuspendedProcess : IDisposable {
    const uint CreateSuspended=4, CreateNoWindow=0x08000000, KillOnClose=0x2000; const int ExtendedLimits=9, ProcessIdInfoClass=3;
    IntPtr process, thread, job, stdoutRead, stderrRead; public int ProcessId { get; private set; } public Process ManagedProcess { get; private set; }
    M12SuspendedProcess(IntPtr p, IntPtr t, IntPtr j, IntPtr output, IntPtr error, int id) { process=p;thread=t;job=j;stdoutRead=output;stderrRead=error;ProcessId=id;ManagedProcess=Process.GetProcessById(id); }
    public Stream StandardOutput => new FileStream(new Microsoft.Win32.SafeHandles.SafeFileHandle(stdoutRead,false),FileAccess.Read,4096,false);
    public Stream StandardError => new FileStream(new Microsoft.Win32.SafeHandles.SafeFileHandle(stderrRead,false),FileAccess.Read,4096,false);
    public static M12SuspendedProcess Start(string executable,string[] args,string workingDirectory) {
        var command=new StringBuilder(Quote(executable)); foreach(var arg in args) command.Append(' ').Append(Quote(arg));
        var si=new STARTUPINFO(); si.cb=Marshal.SizeOf<STARTUPINFO>(); si.flags=0x100; si.input=GetStdHandle(-10); IntPtr outputRead,outputWrite,errorRead,errorWrite; var security=new SECURITY_ATTRIBUTES{length=Marshal.SizeOf<SECURITY_ATTRIBUTES>(),inherit=1}; if(!CreatePipe(out outputRead,out outputWrite,ref security,0)||!CreatePipe(out errorRead,out errorWrite,ref security,0)||!SetHandleInformation(outputRead,1,0)||!SetHandleInformation(errorRead,1,0)) throw new InvalidOperationException("pipe failed"); si.output=outputWrite;si.error=errorWrite; PROCESS_INFORMATION pi;
        if(!CreateProcess(null,command,IntPtr.Zero,IntPtr.Zero,true,CreateSuspended|CreateNoWindow,IntPtr.Zero,workingDirectory,ref si,out pi)) throw new InvalidOperationException("CreateProcess failed"); CloseHandle(outputWrite);CloseHandle(errorWrite);
        var j=CreateJobObject(IntPtr.Zero,null); if(j==IntPtr.Zero) { TerminateProcess(pi.hProcess,1); throw new InvalidOperationException("CreateJobObject failed"); }
        var limits=new EXTENDED_LIMIT_INFORMATION(); limits.BasicLimitInformation.LimitFlags=KillOnClose;
        if(!SetInformationJobObject(j,ExtendedLimits,ref limits,(uint)Marshal.SizeOf<EXTENDED_LIMIT_INFORMATION>() ) || !AssignProcessToJobObject(j,pi.hProcess) || ResumeThread(pi.hThread)==uint.MaxValue) { TerminateJobObject(j,1); throw new InvalidOperationException("job containment failed"); }
        CloseHandle(pi.hThread); return new M12SuspendedProcess(pi.hProcess,IntPtr.Zero,j,outputRead,errorRead,pi.dwProcessId);
    }
    static string Quote(string v) { var b=new StringBuilder("\""); int slash=0; foreach(char c in v) { if(c=='\\'){slash++;continue;} if(c=='\"'){b.Append('\\',slash*2+1).Append('"');slash=0;continue;} b.Append('\\',slash).Append(c);slash=0;} b.Append('\\',slash*2).Append('"');return b.ToString(); }
     public int ActiveProcesses { get { IntPtr b=Marshal.AllocHGlobal(65536); try { if(!QueryInformationJobObject(job,ProcessIdInfoClass,b,65536,IntPtr.Zero)) throw new InvalidOperationException(); return Marshal.ReadInt32(b); } finally { Marshal.FreeHGlobal(b); } } }
     public int[] ProcessIds { get { IntPtr b=Marshal.AllocHGlobal(65536); try { if(!QueryInformationJobObject(job,ProcessIdInfoClass,b,65536,IntPtr.Zero)) throw new InvalidOperationException(); int n=Marshal.ReadInt32(b,4); var ids=new int[n]; for(int i=0;i<n;i++) ids[i]=unchecked((int)Marshal.ReadInt64(b,8+i*IntPtr.Size)); return ids; } finally { Marshal.FreeHGlobal(b); } } }
    public void Terminate() { if(job!=IntPtr.Zero && !TerminateJobObject(job,1)) throw new InvalidOperationException("TerminateJobObject failed"); }
    public bool WaitForZero(int ms) { long until=Environment.TickCount64+ms; while(Environment.TickCount64<until){if(ProcessIds.Length==0)return true;System.Threading.Thread.Sleep(25);}return ProcessIds.Length==0; }
     public void Dispose() { try { if(ActiveProcesses>0)Terminate(); if(!WaitForZero(2000)) throw new InvalidOperationException("process cleanup timeout"); } finally { if(process!=IntPtr.Zero)CloseHandle(process); if(job!=IntPtr.Zero)CloseHandle(job); if(stdoutRead!=IntPtr.Zero)CloseHandle(stdoutRead); if(stderrRead!=IntPtr.Zero)CloseHandle(stderrRead); } }
     [StructLayout(LayoutKind.Sequential)] struct STARTUPINFO { public int cb; public IntPtr reserved,desktop,title; public int x,y,xSize,ySize,xCount,yCount,fill; public uint flags; public short show,reserved2; public IntPtr reserved3,input,output,error; }
     [StructLayout(LayoutKind.Sequential)] struct SECURITY_ATTRIBUTES { public int length; public IntPtr descriptor; public int inherit; }
    [StructLayout(LayoutKind.Sequential)] struct PROCESS_INFORMATION { public IntPtr hProcess,hThread; public int dwProcessId,dwThreadId; }
    [StructLayout(LayoutKind.Sequential)] struct BASIC_LIMIT_INFORMATION { public long a,b; public uint LimitFlags; public UIntPtr c,d; public uint e; public UIntPtr f; public uint g,h; }
    [StructLayout(LayoutKind.Sequential)] struct IO_COUNTERS { public ulong a,b,c,d,e,f; }
    [StructLayout(LayoutKind.Sequential)] struct EXTENDED_LIMIT_INFORMATION { public BASIC_LIMIT_INFORMATION BasicLimitInformation; public IO_COUNTERS IoInfo; public UIntPtr a,b,c,d; }
     [DllImport("kernel32.dll",SetLastError=true)] static extern bool CreatePipe(out IntPtr read,out IntPtr write,ref SECURITY_ATTRIBUTES attributes,uint size=0); [DllImport("kernel32.dll",SetLastError=true)] static extern bool SetHandleInformation(IntPtr handle,uint mask,uint flags); [DllImport("kernel32.dll",SetLastError=true)] static extern IntPtr GetStdHandle(int standardHandle);
    [DllImport("kernel32.dll",CharSet=CharSet.Unicode,SetLastError=true)] static extern bool CreateProcess(string app,StringBuilder cmd,IntPtr pa,IntPtr ta,bool inherit,uint flags,IntPtr env,string cwd,ref STARTUPINFO si,out PROCESS_INFORMATION pi);
    [DllImport("kernel32.dll")] static extern uint ResumeThread(IntPtr thread); [DllImport("kernel32.dll")] static extern IntPtr CreateJobObject(IntPtr a,string n); [DllImport("kernel32.dll")] static extern bool AssignProcessToJobObject(IntPtr j,IntPtr p); [DllImport("kernel32.dll")] static extern bool SetInformationJobObject(IntPtr j,int c,ref EXTENDED_LIMIT_INFORMATION i,uint n); [DllImport("kernel32.dll")] static extern bool QueryInformationJobObject(IntPtr j,int c,IntPtr i,uint n,IntPtr r); [DllImport("kernel32.dll")] static extern bool TerminateJobObject(IntPtr j,uint c); [DllImport("kernel32.dll")] static extern bool TerminateProcess(IntPtr p,uint c); [DllImport("kernel32.dll")] static extern bool CloseHandle(IntPtr h);
}
'@
