        if(-not(Test-Path -LiteralPath $source)){Fail 'PATH'}
        Assert-M12NoReparse $source $SourceRoot; Assert-M12NoAlternateDataStreams $source $SourceRoot
        $sourceItem=Get-Item -LiteralPath $source -Force;if(([int]($sourceItem.Attributes -band $unsafeAttributes))-ne 0){Fail 'PATH'}
        $files=if($sourceItem.PSIsContainer){
            foreach($directory in @(Get-ChildItem -LiteralPath $source -Directory -Force -Recurse)){if(([int]($directory.Attributes -band $unsafeAttributes))-ne 0 -or $directory.Name.StartsWith('.')){Fail 'PATH'};Assert-M12NoReparse $directory.FullName $SourceRoot;Assert-M12NoAlternateDataStreams $directory.FullName $SourceRoot}
            @(Get-ChildItem -LiteralPath $source -File -Force -Recurse)
        } else { @($sourceItem) }
        foreach($file in $files) {
            if($file.Name.StartsWith('.') -or ([int]($file.Attributes -band $unsafeAttributes))-ne 0){Fail 'PATH'}
            Assert-M12NoReparse $file.FullName $SourceRoot;Assert-M12NoAlternateDataStreams $file.FullName $SourceRoot
