            $parent=[IO.Path]::GetDirectoryName($destination);[IO.Directory]::CreateDirectory($parent)|Out-Null
            if(Test-Path -LiteralPath $destination){Fail 'PATH'}
            $temporary="$destination.$([Guid]::NewGuid().ToString('N')).tmp";$stream=$null
            try {$stream=[IO.File]::Open($temporary,[IO.FileMode]::CreateNew,[IO.FileAccess]::Write,[IO.FileShare]::None);$stream.Write($sourceBytes.Bytes,0,$sourceBytes.Bytes.Length);$stream.Flush($true)} finally {if($null-ne$stream){$stream.Dispose()}}
            try {[IO.File]::Move($temporary,$destination)} catch {if(Test-Path -LiteralPath $temporary){Remove-Item -LiteralPath $temporary -Force -ErrorAction Stop};throw}
